output_text:
[
  {
    "id": "entry_cart_required",
    "text": "A shopper must take the entry cart from the entry cart station before completing the trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "entry_cart_pickup": {
          "pre": {
            "and": [
              "entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "entry_cart_pickup"
    }
  },
  {
    "id": "no_cartless_item_pickup",
    "text": "A shopper is prohibited from picking up shelf items unless they currently have the cart.",
    "abstraction": {
      "state_properties": {
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "cartless",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "cart_return_bay_only",
    "text": "A cart may only be put down at the designated cart return bay in the top-left service area.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "away_from_cart_return_bay": {
          "not": "cart_return_bay"
        }
      },
      "events": {
        "cart_put_down_away_from_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "away_from_cart_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_put_down_away_from_bay"
    }
  },
  {
    "id": "park_cart_at_service_if_arriving_with_cart",
    "text": "If a shopper reaches the top-left service point while still pushing a cart, they must park the cart there before exiting.",
    "abstraction": {
      "state_properties": {
        "top_left_service_point": "at(0,1)",
        "at_service_with_cart": {
          "and": [
            "top_left_service_point",
            "hasCart"
          ]
        }
      },
      "events": {
        "service_cart_parked": {
          "pre": {
            "and": [
              "at_service_with_cart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "and": [
              "cartAt(0,1)",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "at_service_with_cart",
      "discharge": "service_cart_parked"
    }
  },
  {
    "id": "do_not_reclaim_returned_service_cart",
    "text": "Once a cart has been returned at the top-left service bay, the shopper should not reclaim that cart.",
    "abstraction": {
      "state_properties": {
        "top_left_service_point": "at(0,1)",
        "service_cart_waiting": "cartAt(0,1)",
        "returned_cart_available": {
          "and": [
            "top_left_service_point",
            "service_cart_waiting"
          ]
        }
      },
      "events": {
        "returned_service_cart_reclaimed": {
          "pre": {
            "and": [
              "returned_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "returned_service_cart_reclaimed"
    }
  },
  {
    "id": "cart_free_exit_requires_service_return",
    "text": "A shopper who exits without a cart must have left the cart parked at the top-left service return bay.",
    "abstraction": {
      "state_properties": {
        "cart_free": {
          "not": "hasCart"
        },
        "service_cart_waiting": "cartAt(0,1)",
        "cart_free_without_service_return": {
          "and": [
            "cart_free",
            {
              "not": "service_cart_waiting"
            }
          ]
        }
      },
      "events": {
        "cart_free_exit_without_service_return": {
          "pre": {
            "and": [
              "EXIT",
              "cart_free_without_service_return"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_free_exit_without_service_return"
    }
  },
  {
    "id": "no_cart_in_upper_right_restricted_cell",
    "text": "The upper-right shortcut cell may be used only when not pushing a cart; entering it with a cart is prohibited.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "upper_right_restricted_cell": "at(8,2)"
      },
      "events": {
        "cart_enters_upper_right_restricted_cell": {
          "pre": {
            "and": [
              "pushing_cart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "pushing_cart",
              "upper_right_restricted_cell"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_enters_upper_right_restricted_cell"
    }
  },
  {
    "id": "depart_service_south_after_parking",
    "text": "After returning the cart at the top-left service bay, the shopper must depart south from that bay while cart-free.",
    "abstraction": {
      "state_properties": {
        "top_left_service_point": "at(0,1)",
        "service_cart_waiting": "cartAt(0,1)",
        "cart_free": {
          "not": "hasCart"
        }
      },
      "events": {
        "service_cart_parked": {
          "pre": {
            "and": [
              "top_left_service_point",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "and": [
              "service_cart_waiting",
              "cart_free"
            ]
          }
        },
        "south_departure_without_cart": {
          "pre": {
            "and": [
              "top_left_service_point",
              "service_cart_waiting",
              "cart_free",
              "S"
            ]
          },
          "post": {
            "and": [
              "at(0,2)",
              "service_cart_waiting",
              "cart_free"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "service_cart_parked",
      "discharge": "south_departure_without_cart"
    }
  }
]
